#include <bits/stdc++.h>
using namespace std;

using ll = long long;

ll p, x, y;

bool check(ll rating) {
    if (rating < y) return false;

    ll value = (rating / 50) % 475;
    for (int i = 0; i < 25; ++i) {
        value = (value * 96 + 42) % 475;
        if (26 + value == p) return true;
    }
    return false;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> p >> x >> y;

    for (ll wins = 0;; ++wins) {
        ll rating = x + 100 * wins;
        ll attempts = min(475LL, (rating - y) / 50 + 1);

        for (ll losses = 0; losses < attempts; ++losses) {
            if (check(rating - 50 * losses)) {
                cout << wins;
                return 0;
            }
        }
    }
}

